var builder = WebApplication.CreateBuilder(args);
builder.Services.AddAuthentication().AddJwtBearer();
builder.Services.AddAuthorization();
var app = builder.Build();

app.UseAuthentication();
app.Use(async (context, next) =>
{
    // Guards one exact string: other verbs and URL shapes skip it
    if (context.Request.Path == "/api/orders"
        && HttpMethods.IsPost(context.Request.Method))
    {
        context.Request.EnableBuffering(); // parse now, parse again later
        var order = await context.Request.ReadFromJsonAsync<OrderRequest>();
        context.Request.Body.Position = 0;
        if (order?.CustomerId != context.User.FindFirst("customer_id")?.Value)
        {
            context.Response.StatusCode = StatusCodes.Status403Forbidden;
            return;
        }
    }
    await next(context);
});
app.MapGroup("/api/orders").RequireAuthorization().MapOrders();
app.Run();

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddAuthentication().AddJwtBearer();
builder.Services.AddAuthorization();
var app = builder.Build();

app.MapGroup("/api/orders")
    .RequireAuthorization()
    .AddEndpointFilter<OwnCustomerOnly>() // every endpoint in the group
    .MapOrders();
app.Run();

public sealed class OwnCustomerOnly : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(
        EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        var caller = context.HttpContext.User.FindFirst("customer_id")?.Value;
        // Arguments are already bound: no second parse of the body
        foreach (var owned in context.Arguments.OfType<ICustomerOwned>())
            if (owned.CustomerId != caller) return TypedResults.Forbid();
        return await next(context);
    }
}
